import {createGame,people,factions,roads,citySeed,actor,owned,authority,economyPreview,foodCapacity,order,setPolicy,interact,march,advance,resolve,restore,succeed,recruit,appoint,startingCity} from './engine.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('ko-KR');
const KEY='three-kingdom.save.v1';let state=null,tab='천하',selected=0,peopleFilter='all',saveError='',toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)state=restore(raw);}catch{saveError='저장을 읽지 못했습니다. 새 게임 시작 전에 저장 파일을 확인하세요.';}
if(state)selected=startingCity(state);
const icons=[`<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>`,`<path d="M3 21h18M5 21V8l7-5 7 5v13M9 21v-7h6v7M9 9h6"/>`,`<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>`,`<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>`,`<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="19" r="2"/>`];
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveError='';}catch{saveError='기기 저장에 실패했습니다. 더 보기에서 저장 파일을 내보내세요.';toast(saveError);}}
function date(day){return `중평 원년 · 제${day+1}일`;}
function logs(n=5){return state.logs.slice(0,n).map(l=>`<div class="list-item"><div class="log-date">${date(l.day)}</div><div class="log-text">${esc(l.text)}</div></div>`).join('');}
function playerPreview(id){const p=people.find(x=>x[0]===id)||people.find(x=>x[0]==='liubei');return `<div class="preview-card"><div class="row"><div class="officer"><div class="portrait hero-portrait">${p[1][0]}</div><div><span class="eyebrow">184 · ${factions[p[2]]}</span><h3>${p[1]}</h3><p class="muted">${p[3]} · ${p[8]}</p></div></div><span class="tag">${p[7]!==null?citySeedName(p[7]):'재야'}</span></div><div class="preview-stats">${['통','무','지','정','매'].map((n,i)=>`<span>${n}<b>${p[4][i]}</b></span>`).join('')}</div><p class="preview-goal">${p[9]}</p></div>`;}
function citySeedName(id){return citySeed[id]?.[0]||'임지 미정';}
function start(){return `<div class="start"><div class="start-kicker"><span>184 · 후한 중평 원년</span><span>싱글 플레이</span></div><div class="start-title"><div class="eyebrow">THREE KINGDOMS</div><h1>황건의 봄</h1><p>한 사람의 출사에서 천하의 판도까지.</p></div><div class="start-step"><span class="step-no">01</span><div><div class="kicker">첫 번째 선택</div><h2>누구의 시점으로 시작할까요?</h2><p class="muted">장수의 위치와 권한은 인물마다 달라요.</p></div></div><label for="player">역사 인물 · 11명</label><select id="player">${people.filter(p=>p[2]!==2).map(p=>`<option value="${p[0]}" ${p[0]==='liubei'?'selected':''}>${p[1]} · ${p[3]} · ${factions[p[2]]}</option>`).join('')}</select><div id="player-preview">${playerPreview('liubei')}</div><button class="btn primary start-button" data-action="start">이 인물로 출사하기 <span>→</span></button><div class="start-promises"><span>기기 저장</span><span>매일 직접 진행</span><span>유료 API 없음</span></div><details class="start-help"><summary>게임 방식 미리보기</summary><p>하루 단위로 시간을 진행하고, 중요 사건은 선택할 때까지 멈춰요. 전투는 도시와 장수의 조건에 따라 자동으로 결판납니다. 종료해도 시간은 흐르지 않아요.</p></details>${saveError?`<div class="notice">${esc(saveError)}</div><button class="btn" data-action="import">저장 파일 불러오기</button>`:''}</div>`;}
function map(){return `<div class="map-wrap"><svg class="map" viewBox="0 0 480 500" role="img" aria-label="중원 일부 도시 연결 지도. 후한 토벌군은 초록색, 황건군은 황갈색입니다."><path class="water" d="M-20 180 Q60 225 130 175 T260 208 T490 200M-20 415Q80 440 175 401T365 463T500 437"/><g class="mount"><path d="m17 112 18-26 20 26m-12 0 24-38 23 38m245 272 24-31 23 31m-8-5 17-26 22 26M20 309l18-28 16 28m-9 0 17-30 20 30"/></g>${roads.map(([a,b])=>`<line class="road" x1="${state.cities[a].x}" y1="${state.cities[a].y}" x2="${state.cities[b].x}" y2="${state.cities[b].y}"/>`).join('')}${state.armies.map(a=>{const f=state.cities[a.from],t=state.cities[a.to],v=1-a.days/a.total;return `<circle cx="${f.x+(t.x-f.x)*v}" cy="${f.y+(t.y-f.y)*v}" r="5" fill="#c8a048" stroke="#fff" stroke-width="2"/>`;}).join('')}${state.cities.map(c=>`<g class="node" role="button" tabindex="0" aria-label="${c.name}，${factions[c.faction]}，兵力${fmt(c.troops)}" data-city="${c.id}">${c.id===selected?`<circle class="ring" cx="${c.x}" cy="${c.y}" r="20"/>`:''}<circle cx="${c.x}" cy="${c.y}" r="12" fill="${c.faction===0?'#32594a':'#b77940'}" stroke="#f4f0e6" stroke-width="3"/><text x="${c.x}" y="${c.y+32}" text-anchor="middle">${c.name}</text></g>`).join('')}</svg><div class="legend"><span><i class="dot"></i>후한 토벌군</span><span><i class="dot enemy"></i>황건군</span><span>● 이동 부대</span></div></div>`;}
function cityCard(c,full=false){const a=owned(state,c.id)?authority(state,c.id):null,g=c.governor?state.people.find(p=>p.id===c.governor)?.name:'공석',r=economyPreview(c,state.people);return `<div class="card"><div class="row"><h3>${c.name}</h3><span class="tag ${c.faction===1?'enemy':''}">${factions[c.faction]}</span></div><p class="muted" style="margin-top:7px">${esc(c.historicNote)} · 책임자 ${esc(g||'공석')}</p><div class="stats"><div class="stat"><small>병력</small><strong>${fmt(c.troops)}</strong></div><div class="stat"><small>자금</small><strong>${fmt(c.gold)}</strong></div><div class="stat"><small>군량</small><strong>${fmt(c.food)}</strong></div></div>${full?`<div class="economy-summary"><div><small>인구</small><b>${fmt(c.population)}명</b></div><div><small>주간 자금</small><b class="${r.goldWeekly<0?'negative':''}">${r.goldWeekly>0?'+':''}${fmt(r.goldWeekly)}</b></div><div><small>주간 군량</small><b class="${r.foodWeekly<0?'negative':''}">${r.foodWeekly>0?'+':''}${fmt(r.foodWeekly)}</b></div><div><small>군량 저장 한도</small><b>${fmt(foodCapacity(c))}</b></div></div><div class="row muted" style="margin-top:12px"><span>농업 ${c.farm}</span><span>훈련 ${c.training}</span><span>사기 ${c.morale}</span></div>${a?`<div class="notice"><strong>${a.label}</strong><br>${a.detail}</div>`:''}`:''}${c.task?`<div class="notice">${c.task.type} 수행 중 · ${c.task.left}일 남음</div>`:''}${!full?`<div class="row" style="margin-top:16px"><span class="muted">${owned(state,c.id)?a.label:'상대 세력 도시'} · 인구 ${fmt(c.population)}</span>${owned(state,c.id)?`<button class="btn small" data-action="manage">도시 보기 →</button>`:`<button class="btn small" data-action="campaign">출진 계획 →</button>`}</div>`:''}</div>`;}

function world(){const p=actor(state),home=state.cities[p.station],appointed=state.cities.find(c=>c.governor===p.id),goal=['대장군','군주','황건 수령','태수','현령'].includes(p.role)?'직할지의 병참과 병력을 정비해 연결된 전선을 선택':'임지에서 공적 30을 쌓아 현령으로 부임',progress=Math.min(100,Math.round(p.merit/30*100));return `<div class="eyebrow">CAMPAIGN · 184</div><section class="home-card"><div class="home-top"><div><span class="home-date">${date(state.day)} · ${p.role}</span><h2>${home?.name||p.historicRole}</h2><p class="home-sub">${appointed?`${appointed.name}의 책임자로 재임 중`:`${home?.historicNote||'현재 임지'}`}</p></div><div class="home-seal">${p.name[0]}</div></div><div class="home-resources">${[['병력',home?.troops],['자금',home?.gold],['군량',home?.food],['인구',home?.population]].map(([label,value])=>`<div><small>${label}</small><b>${fmt(value||0)}</b></div>`).join('')}</div><div class="home-goal"><div class="row"><strong>이번 여정</strong><span>${['대장군','군주','황건 수령','태수','현령'].includes(p.role)?'군주 목표':`공적 ${p.merit} / 30`}</span></div><p>${goal}</p>${!['대장군','군주','황건 수령','태수','현령'].includes(p.role)?`<div class="goal-meter"><i style="width:${progress}%"></i></div>`:''}</div><button class="home-action" data-action="manage-home">임지 살펴보기 <span>→</span></button></section><div class="section-title map-heading"><div><div class="eyebrow">THE WORLD</div><h2>천하의 흐름</h2></div><span class="muted">${state.cities.length}개 거점 · 부대 ${state.armies.length}</span></div>${map()}${cityCard(state.cities[selected])}<div class="section-title subhead"><h3>최근 소식</h3><button class="btn small" data-tab="기록">기록 전체 →</button></div><div class="card log-card">${logs(3)}</div>`;}
function cities(){
 const c=state.cities[selected],p=actor(state),mine=state.cities.filter(x=>owned(state,x.id)),a=authority(state,c.id);
 const appointees=state.people.filter(q=>q.alive&&q.faction===p.faction&&q.id!==p.id&&q.role!=='재야'&&!state.cities.some(x=>x.governor===q.id)).sort((x,y)=>y.stats[3]-x.stats[3]);
 const lockReason=state.pending?'중요 사건을 먼저 결정해야 명령할 수 있습니다.':c.task?`${c.task.type} 진행 중 · ${c.task.left}일 후 다음 명령 가능`:a.level==='none'?a.detail:'';
 return `<div class="eyebrow">GOVERNANCE</div><div class="section-title"><h2>도시와 군정</h2><span class="muted">${mine.length}개 아군 거점</span></div><div class="city-chips">${mine.map(x=>{const label=x.governor===p.id?'직할':x.id===p.station?'임지':'아군';return `<button class="chip ${x.id===c.id?'selected':''}" data-select-city="${x.id}" aria-pressed="${x.id===c.id}">${x.name} · ${label}</button>`;}).join('')}</div>${cityCard(c,true)}<div class="section-title subhead"><h3>내정 지시</h3><span class="muted">${a.label}</span></div>${lockReason?`<div class="notice action-status">${esc(lockReason)}</div>`:''}<div class="grid2 city-action-grid">${[['개발','5일 · 농업 +8 · 자금 250'],['훈련','3일 · 훈련 +8 · 자금 180'],['징병','4일 · 병력 +1,000 · 인구 -1,000'],['군량','3일 · 군량 +3,500 · 자금 250']].map(([t,d])=>`<button class="btn" data-order="${t}" ${c.task||state.pending||a.level==='none'?'disabled':''}>${a.level==='lead'?t+' 건의':t}<br><small class="muted">${d}</small></button>`).join('')}</div><div class="card" style="margin-top:14px"><h3>도시 운영 위임</h3><p class="muted" style="margin:8px 0">농업: 주간 자금 80을 써 농업·인구 성장 강화<br>군비: 주간 자금 100과 인구 200으로 병력 증원<br>균형: 세금·급료·군량 수지를 유지<br>태수의 정치력이 세수에 반영</p>${a.level==='command'?`<label for="policy">현재 방침</label><select id="policy">${['균형','농업','군비'].map(v=>`<option ${c.order===v?'selected':''}>${v}</option>`).join('')}</select>`:`<p class="muted">${a.detail}</p>`}</div>${a.level==='command'&&!c.governor?`<div class="card appointment-card" style="margin-top:14px"><div class="row"><h3>도시 책임자 임관</h3><span class="tag">빈 자리</span></div><p class="muted" style="margin:8px 0">정치력이 높은 인물을 우선 보여줘요. 임관하면 이 도시의 태수가 됩니다.</p>${appointees.length?`<div class="row appointment-row"><select id="appoint-person" aria-label="임관할 인물 선택">${appointees.map(q=>`<option value="${q.id}">${q.name} · ${q.role} · 정치 ${q.stats[3]}</option>`).join('')}</select><button class="btn small" data-action="appoint">임관</button></div>`:`<p class="empty">임관할 수 있는 미배치 인물이 없습니다. 먼저 재야 인재를 등용하거나 다른 도시의 책임자를 조정하세요.</p>`}</div>`:c.governor?`<div class="card appointment-card" style="margin-top:14px"><h3>도시 책임자</h3><p class="muted" style="margin-top:8px">${esc(state.people.find(q=>q.id===c.governor)?.name||'인물 미상')} 태수가 이 도시를 맡고 있습니다.</p></div>`:''}<div class="section-title subhead"><h3>출진 계획</h3></div><div class="card"><p class="muted">임지 또는 직할지에서만 지휘관으로 출진합니다. 부대는 도착한 날 자동 전투를 치릅니다.</p>${campaign(c)}</div>${armies()}`;
}
function campaign(c){const right=authority(state,c.id),targets=state.cities.filter(t=>t.faction!==c.faction&&roads.some(r=>r.includes(t.id)&&r.includes(c.id)));if(right.level==='none')return `<p class="empty">${right.detail}</p>`;if(!targets.length)return '<p class="empty">이 도시와 연결된 적 도시가 없습니다.</p>';return `<label for="target">목표 도시</label><select id="target">${targets.map(t=>`<option value="${t.id}">${t.name} · 수비병 ${fmt(t.troops)}</option>`).join('')}</select><label for="troops">출진 병력 · 수비병 1,000명 유지</label><input id="troops" type="number" min="1000" max="${Math.max(1000,c.troops-1000)}" step="500" value="${Math.max(1000,Math.min(4000,c.troops-1000))}"><div class="grid2"><div><label for="unit">병종</label><select id="unit"><option>보병</option><option>기병</option><option>궁병</option></select></div><div><label for="tactic">작전</label><select id="tactic"><option>신중</option><option>강습</option><option>포위</option></select></div></div><p class="muted" style="margin:12px 0">기병은 평지에 유리하고 험지에 불리합니다. 포위는 이동이 늦고, 강습은 패배 시 손실이 큽니다. 보급 출발지를 빼앗기면 전력이 감소합니다.</p><button class="btn primary" style="width:100%" data-action="march" ${state.pending||state.armies.some(a=>a.leader===state.player)?'disabled':''}>군령 전달 · 출진</button>`;}
function armies(){return `<div class="section-title subhead"><h3>이동 중인 부대</h3><span class="muted">${state.armies.length}개</span></div><div class="card">${state.armies.length?state.armies.map(a=>`<div class="list-item"><div class="row"><strong>${state.cities[a.from].name} → ${state.cities[a.to].name}</strong><span class="tag">${a.days}일 남음</span></div><div class="progress"><i style="width:${100*(1-a.days/a.total)}%"></i></div><div class="muted">${a.unit} ${fmt(a.troops)}명 · ${a.tactic}</div></div>`).join(''):'<div class="empty">아직 출진한 부대가 없습니다.</div>'}</div>`;}
function officers(){
 const p=actor(state),recruits=state.people.filter(q=>q.alive&&q.faction===2),homes=state.cities.filter(c=>c.faction===p.faction&&authority(state,c.id).level!=='none'),affordableHomes=homes.filter(c=>c.gold>=800),readyCount=recruits.filter(q=>state.day>=(q.extensions?.availableFrom||0)).length,atCapacity=state.people.filter(q=>q.alive&&q.faction===p.faction).length>=14;
 const appointable=state.people.filter(q=>q.alive&&q.faction===p.faction&&q.id!==p.id&&q.role!=='재야'&&!state.cities.some(c=>c.governor===q.id)).sort((a,b)=>b.stats[3]-a.stats[3]),vacancies=state.cities.filter(c=>c.faction===p.faction&&authority(state,c.id).level==='command'&&!c.governor);
 return `<div class="eyebrow">PEOPLE & AMBITION</div><div class="section-title"><h2>인물과 인재</h2><span class="muted">등용 가능 ${readyCount}명 · 세력 인물 ${state.people.filter(q=>q.faction!==2).length}명</span></div><div class="card"><div class="officer"><div class="portrait">${p.name[0]}</div><div><h3>${p.name} <span class="tag">${p.role}</span></h3><p class="muted">${factions[p.faction]} · ${p.historicRole} · 공적 ${p.merit}</p></div></div><div class="abilities">${['통솔','무력','지력','정치','매력'].map((a,i)=>`<span>${a}<strong>${p.stats[i]}</strong></span>`).join('')}</div><p class="muted">야망 ${p.ambition} · 의리 ${p.loyalty}<br>주둔: ${state.cities[p.station]?.name||p.historicRole}.</p></div>${vacancies.length?`<div class="card appointment-card"><div class="row"><h3>빈 도시 태수 임관</h3><span class="tag">${vacancies.length}곳</span></div><p class="muted" style="margin:8px 0">정치력 기준으로 인물을 골라 빈 관할 도시에 배치합니다.</p>${appointable.length?`<div class="row appointment-row"><select id="roster-appoint-person" aria-label="임관할 인물 선택">${appointable.map(q=>`<option value="${q.id}">${q.name} · ${q.role} · 정치 ${q.stats[3]}</option>`).join('')}</select><select id="roster-appoint-city" aria-label="태수로 보낼 도시">${vacancies.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><button class="btn small" data-action="appoint-roster">임관</button></div>`:`<p class="empty">임관할 미배치 인물이 없습니다. 먼저 재야 인재를 등용하세요.</p>`}</div>`:''}<div class="section-title subhead"><h3>재야 인재</h3><span class="muted">등용 시도 800 · 실패해도 소모</span></div>${atCapacity?`<div class="notice action-status">현재 세력 인원 한도에 도달해 추가 등용을 할 수 없습니다.</div>`:''}${recruits.length?recruits.map(q=>{const ready=state.day>=(q.extensions?.availableFrom||0),homesWithFunds=affordableHomes;return `<div class="card recruit-card"><div class="row"><div class="officer"><div class="portrait">${q.name[0]}</div><div><h3>${q.name}</h3><p class="muted">${ready?'지금 등용 시도 가능':`등장까지 ${q.extensions?.availableFrom-state.day}일`} · 매력 ${q.stats[4]}</p></div></div><span class="tag">재야</span></div><p class="muted recruit-goal">${esc(q.goal)} · 의리 ${q.loyalty}</p>${ready&&!atCapacity?homesWithFunds.length?`<div class="row recruit-actions"><label class="sr-only" for="recruit-city-${q.id}">${q.name}를 등용할 도시</label><select id="recruit-city-${q.id}" data-recruit-city="${q.id}">${homesWithFunds.map(c=>`<option value="${c.id}">${c.name} · 자금 ${fmt(c.gold)}</option>`).join('')}</select><button class="btn small" data-recruit="${q.id}" ${state.pending?'disabled':''}>등용</button></div>`:homes.length?`<p class="empty">등용 권한은 있지만, 자금 800 이상인 도시가 없습니다.</p>`:`<p class="empty">권한 있는 아군 임지에서만 등용할 수 있습니다.</p>`:!ready?`<p class="empty">역사 전개에 따라 ${q.extensions?.availableFrom||0}일째 이후 등장합니다.</p>`:''}</div>`;}).join(''):'<div class="card empty">현재 재야 인재가 없습니다. 시간을 진행하면 역사 전개에 따라 후보가 나타납니다.</div>'}<div class="section-title subhead"><h3>인물 동향</h3><span class="muted">목표와 최근 행동</span></div><div class="filter-pills">${[['all','전체'],['ally','동료'],['enemy','적 세력']].map(([id,label])=>`<button class="chip ${peopleFilter===id?'selected':''}" data-people-filter="${id}" aria-pressed="${peopleFilter===id}">${label}</button>`).join('')}</div>${state.people.filter(q=>q.id!==p.id&&q.alive&&q.faction!==2&&(peopleFilter==='all'||(peopleFilter==='ally'?q.faction===p.faction:q.faction!==p.faction))).map(q=>`<div class="card"><div class="row"><div class="officer"><div class="portrait">${q.name[0]}</div><div><h3>${q.name}</h3><p class="muted">${factions[q.faction]} · ${q.role} · ${state.cities[q.station]?.name||'원정 중'}</p></div></div><span class="tag ${q.faction===p.faction?'':'enemy'}">${q.faction===p.faction?'동료':'상대'}</span></div><p class="muted" style="margin-top:12px">현재 목표 · ${esc(q.goal)}${q.lastAction?`<br>최근 행동 · ${esc(q.lastAction)}`:''}</p><div class="row" style="margin-top:13px"><span class="muted">친밀도 ${p.relations[q.id]||0} · 통솔 ${q.stats[0]}</span>${q.faction===p.faction?`<button class="btn small" data-talk="${q.id}" ${state.pending||p.lastTalk===state.day||q.station!==p.station?'disabled':''} title="${q.station===p.station?'같은 주둔지에서 교류할 수 있습니다':'같은 주둔지에 있을 때 교류할 수 있습니다'}">${q.station===p.station?'교류하기':'다른 주둔지'}</button>`:''}</div></div>`).join('')}`;
}
function more(){return `<div class="eyebrow">YOUR JOURNEY</div><div class="section-title"><h2>나의 여정</h2><span class="muted">v0.5.1</span></div><div class="card"><h3>저장과 이어하기</h3><p class="muted" style="margin-top:10px">행동과 시간 진행 후 기기에 자동 저장합니다. 브라우저 데이터를 지우면 저장도 사라집니다. 다른 기기로 옮기려면 파일을 내보내세요.</p><div class="setting-buttons"><button class="btn primary" data-action="export">저장 파일 내보내기</button><button class="btn" data-action="import">저장 파일 불러오기</button></div>${saveError?`<div class="notice">${esc(saveError)}</div>`:''}</div><div class="card"><h3>함께 만들고 있는 삼국지</h3><div class="notice">현재: 11개 도시와 14명 인물, 재야 등용, 인물 임관, NPC 자율 등용·도시 배치·내정·군령·출진, 일 단위 진행, 사건 중단, 저장.</div><p class="muted">다음: 세력 간 외교, 인물의 독립·포로·사망과 계승, 역사 사건 확장.<br><br>추후 확장: 혼인·자녀·가문·개인 재산·사제 관계, 능력별 전문성.<br><br>코에이 작품을 참고한 독자 구현입니다. 해당 작품의 이미지·음악·코드·데이터를 사용하지 않습니다.</p><p style="margin-top:15px"><a href="https://github.com/hj0044/three-kingdom" target="_blank" rel="noopener" style="color:var(--green)">개발 리포지터리 ↗</a></p></div><div class="danger-zone"><button class="btn danger" style="width:100%" data-action="reset">새로운 여정 시작</button></div>`;}
function render(){
 if(!state){$('#app').innerHTML=start();return;}
 if(tab==='도시'&&!owned(state,selected)){const c=state.cities.find(c=>owned(state,c.id));if(c)selected=c.id;else tab='천하';}
 const p=actor(state),views={'천하':world,'도시':cities,'인물':officers,'기록':()=>`<div class="eyebrow">CHRONICLE</div><div class="section-title"><h2>난세의 기록</h2><span class="muted">최근 100건</span></div><div class="card">${logs(100)}</div>`,'더 보기':more};
 $('#app').innerHTML=`<header><div class="top"><div class="brand">삼국지</div><span class="badge">황건의 봄 · 개발판</span></div><div class="date">${date(state.day)} · ${state.day}일째</div><div class="identity"><strong>${esc(p.name)}</strong><span>${p.role} / ${factions[p.faction]}</span></div></header><div class="banner">184 황건의 난 · 역사 기반 재구성 · 능력치는 게임용</div><main>${views[tab]()}</main><div class="controls"><div class="row"><span>${state.pending?'중요한 보고가 도착했습니다':'명령을 정했다면 시간을 진행하세요'}</span><span>${saveError?'저장 확인 필요':'기기 자동 저장'}</span></div><div class="time-buttons">${[1,7,30].map(n=>`<button class="btn ${n===7?'primary':''}" data-days="${n}" ${state.pending||!p.alive?'disabled':''}>${n}일 진행</button>`).join('')}</div></div><nav class="nav" aria-label="주 메뉴">${Object.keys(views).map((t,i)=>`<button data-tab="${t}" class="${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[i]}</svg>${t}</button>`).join('')}</nav>${state.pending?`<dialog id="event"><div class="eyebrow">IMPORTANT DISPATCH</div><h2>${esc(state.pending.title)}</h2><p>${esc(state.pending.text)}</p>${['history','promotion'].includes(state.pending.kind)?'<div class="grid2"><button class="btn" data-choice="decline">거절</button><button class="btn primary" data-choice="accept">수락</button></div>':'<button class="btn primary" style="width:100%" data-choice="confirm">확인하고 계속</button>'}</dialog>`:''}${!p.alive?`<dialog id="succession"><h2>다음 인물로 이어가기</h2><p>세계는 계속됩니다. 생존 인물을 선택하세요.</p><select id="heir">${state.people.filter(q=>q.alive).map(q=>`<option value="${q.id}">${q.name}</option>`).join('')}</select><button class="btn primary" data-action="succeed">이 인물로 계속</button></dialog>`:''}`;
 if($('#event')){$('#event').showModal();$('#event').addEventListener('cancel',e=>e.preventDefault());}
 if($('#succession')){$('#succession').showModal();$('#succession').addEventListener('cancel',e=>e.preventDefault());}
}
function perform(fn){try{fn();save();render();}catch(e){toast(e.message);}}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-city]');if(!b)return;const a=b.dataset.action;
 if(b.dataset.tab){tab=b.dataset.tab;render();window.scrollTo(0,0);return;}
 if(b.dataset.peopleFilter){peopleFilter=b.dataset.peopleFilter;render();return;}
 if(b.dataset.city!==undefined){selected=Number(b.dataset.city);render();return;}
 if(b.dataset.selectCity!==undefined){selected=Number(b.dataset.selectCity);render();return;}
 if(b.dataset.days){perform(()=>{const moved=advance(state,Number(b.dataset.days));toast(`${moved}일이 흘렀습니다.${state.pending?' 중요한 보고가 도착해 멈췄습니다.':''}`);});return;}
 if(b.dataset.order){perform(()=>order(state,selected,b.dataset.order));return;}
 if(b.dataset.talk){perform(()=>interact(state,b.dataset.talk));return;}
 if(b.dataset.recruit){const id=b.dataset.recruit,select=document.querySelector(`[data-recruit-city=\"${id}\"]`),q=state.people.find(p=>p.id===id);perform(()=>{const ok=recruit(state,id,Number(select.value));toast(ok?`${q.name}이 등용에 응했습니다.`:`${q.name}이 출사를 미뤘습니다. 자금 800은 사용됐어요.`);});return;}
 if(a==='appoint')perform(()=>{const id=$('#appoint-person').value,q=state.people.find(p=>p.id===id);appoint(state,id,selected);toast(`${q.name}을 ${state.cities[selected].name} 태수로 임관했습니다.`);});
 if(a==='appoint-roster')perform(()=>{const id=$('#roster-appoint-person').value,city=Number($('#roster-appoint-city').value),q=state.people.find(p=>p.id===id);appoint(state,id,city);selected=city;tab='도시';toast(`${q.name}을 ${state.cities[city].name} 태수로 임관했습니다.`);});
 if(b.dataset.choice){perform(()=>resolve(state,b.dataset.choice));return;}
 if(a==='start'){if(saveError&&!confirm('새 게임을 시작하면 기기의 기존 저장을 덮어쓸 수 있습니다. 시작할까요?'))return;perform(()=>{state=createGame($('#player').value);selected=startingCity(state);});}
 if(a==='manage'||a==='manage-home'){if(a==='manage-home')selected=startingCity(state);tab='도시';render();window.scrollTo(0,0);}
 if(a==='campaign'){const enemy=selected;const origin=state.cities.find(c=>owned(state,c.id)&&roads.some(r=>r.includes(c.id)&&r.includes(enemy)));if(!origin){toast('연결된 아군 도시가 없습니다.');return;}selected=origin.id;tab='도시';render();if($('#target'))$('#target').value=enemy;$('#target')?.scrollIntoView({behavior:'smooth',block:'center'});}
 if(a==='march')perform(()=>march(state,selected,Number($('#target').value),Number($('#troops').value),$('#tactic').value,$('#unit').value));
 if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`three-kingdom-day-${state.day}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.');}
 if(a==='import')$('#import').click();
 if(a==='reset'&&confirm('현재 진행을 끝내고 새 인물을 선택할까요? 필요하면 먼저 저장 파일을 내보내세요.')){try{localStorage.removeItem(KEY);}catch{toast('기기 저장을 삭제하지 못했습니다.');return;}state=null;tab='천하';render();}
 if(a==='succeed')perform(()=>succeed(state,$('#heir').value));
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-city]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{if(e.target.id==='player')$('#player-preview').innerHTML=playerPreview(e.target.value);if(e.target.id==='city'){selected=Number(e.target.value);render();}if(e.target.id==='policy')perform(()=>setPolicy(state,selected,e.target.value));});
$('#import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('저장 파일은 500KB 이하여야 합니다.');const next=restore(await f.text());if(state&&!confirm('현재 진행을 파일의 저장으로 교체할까요?'))return;state=next;tab='천하';selected=startingCity(state);save();render();toast('저장된 여정을 불러왔습니다.');}catch(err){toast(err.message);}finally{e.target.value='';}});
render();
